$ErrorActionPreference = "Stop"
$BaseDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$OutputDir = Join-Path $BaseDir "bangla-text-tools"
$PayloadB64 = ""
if (Test-Path $OutputDir) { Remove-Item $OutputDir -Recurse -Force }
New-Item -ItemType Directory -Path $OutputDir -Force | Out-Null
$PayloadPath = Join-Path $BaseDir ".btt-payload.zip"
[IO.File]::WriteAllBytes($PayloadPath,[Convert]::FromBase64String($PayloadB64))
Add-Type -AssemblyName System.IO.Compression.FileSystem
[IO.Compression.ZipFile]::ExtractToDirectory($PayloadPath,$OutputDir)
Copy-Item $MyInvocation.MyCommand.Path (Join-Path $OutputDir "setup.ps1") -Force
$ShellSetup = Join-Path $BaseDir "setup.sh"
if (Test-Path $ShellSetup) { Copy-Item $ShellSetup (Join-Path $OutputDir "setup.sh") -Force }
Remove-Item $PayloadPath -Force
$ZipPath = Join-Path $BaseDir "bangla-text-tools.zip"
if (Test-Path $ZipPath) { Remove-Item $ZipPath -Force }
[IO.Compression.ZipFile]::CreateFromDirectory($OutputDir,$ZipPath)
Write-Host "Created $OutputDir"
Write-Host "Created $ZipPath"
